/* ========== TYPES ========== */
type SessionType = 'free' | 'paid';
type Owner = null | 'me' | 'other';
type Status = 'ongoing' | 'end'; // mock state (backend)
type UiPhase = 'selling' | 'waiting' | 'drawing' | 'finished';

type Ball = string; // '01'..'99'

interface ResultsMock {
  result_1: Ball; // main
  result_2: Ball; // second
  result_3: Ball; // third
  wins: Array<{ ball: Ball; user: string }>;
}

interface Session {
  id: string;
  name: string;
  type: SessionType;
  stake: number;
  postSellDelayMin: number;
  payoutsMultipliers: [number, number, number];
  purchased: { all: Ball[]; mine: Ball[] };
  limitPerUser: number | null; // null = illimité
  status: Status; // "ongoing" ou "end"
  results?: ResultsMock; // présent si status === "end"
}

interface Cell {
  n: Ball;
  owner: Owner;
}

/* ========== HELPERS ========== */
const BALLS: Ball[] = Array.from({ length: 99 }, (_, i) => (i + 1).toString().padStart(2, '0'));
const money = (n: number) => n.toLocaleString('en-US');

const baseBoard = (): Cell[] => BALLS.map((b) => ({ n: b, owner: null }));

const buildBoardFromSession = (s: Session): Cell[] => {
  const board = baseBoard();
  const sold = new Set<Ball>(s.purchased.all);
  const mine = new Set<Ball>(s.purchased.mine);
  mine.forEach((n) => sold.add(n));
  const mapIdx = new Map<Ball, number>();
  board.forEach((c, i) => mapIdx.set(c.n, i));
  sold.forEach((num) => {
    const i = mapIdx.get(num);
    if (i !== undefined) board[i].owner = 'other';
  });
  mine.forEach((num) => {
    const i = mapIdx.get(num);
    if (i !== undefined) board[i].owner = 'me';
  });
  return board;
};

const maskName = (name: string) => {
  return name
    .split(' ')
    .filter(Boolean)
    .map((part) =>
      part.length <= 1 ? part : part[0] + '*'.repeat(Math.max(1, Math.min(3, part.length - 1)))
    )
    .join(' ');
};

