/* ========== GAME ========== */
function RafGame({ initialSession, onBack }: { initialSession: Session; onBack: () => void }) {
  const theme = useTheme();
  const isXs = useMediaQuery(theme.breakpoints.down('sm'));
  const isMd = useMediaQuery(theme.breakpoints.down('md'));

  const [session, setSession] = useState<Session>(initialSession);
  const [board, setBoard] = useState<Cell[]>(buildBoardFromSession(initialSession));
  const [myTickets, setMyTickets] = useState<Ball[]>(
    Array.from(new Set(initialSession.purchased.mine))
  );
  const [selected, setSelected] = useState<Ball | null>(null);

  // UI phase depends on mock status
  const [phase, setPhase] = useState<UiPhase>(() =>
    initialSession.status === 'end' ? 'finished' : 'selling'
  );

  const [countdown, setCountdown] = useState<number>(0);
  const [revealed, setRevealed] = useState<Ball[]>([]);
  const [autoSell, setAutoSell] = useState<boolean>(false);

  // winners → from mock if status=end, else local draw
  const initWinners: Ball[] =
    initialSession.status === 'end' && initialSession.results
      ? [
          initialSession.results.result_1,
          initialSession.results.result_2,
          initialSession.results.result_3,
        ]
      : [];
  const [winners, setWinners] = useState<Ball[]>(initWinners);

  const revealTimerRef = useRef<NodeJS.Timeout | null>(null);
  const autoSellRef = useRef<NodeJS.Timeout | null>(null);
  const drawProgressRef = useRef<NodeJS.Timeout | null>(null);

  const totalSold = useMemo(() => board.filter((c) => c.owner !== null).length, [board]);
  const soldOut = totalSold === 99;

  // progress bar value (animated in WAITING + DRAWING)
  const delayTotal = session.postSellDelayMin * 60 || 1;
  const [drawingProgress, setDrawingProgress] = useState<number>(0);
  const progressValue = useMemo(() => {
    if (phase === 'selling') return (totalSold / 99) * 100;
    if (phase === 'waiting') return ((delayTotal - countdown) / delayTotal) * 100;
    if (phase === 'drawing') return drawingProgress;
    if (phase === 'finished') return 100;
    return 0;
  }, [phase, totalSold, delayTotal, countdown, drawingProgress]);

  const progressAnimation =
    phase === 'waiting' || phase === 'drawing'
      ? {
          '& .MuiLinearProgress-bar': { animation: 'pulse 1.2s ease-in-out infinite' },
          '@keyframes pulse': {
            '0%': { filter: 'brightness(1)' },
            '50%': { filter: 'brightness(1.4)' },
            '100%': { filter: 'brightness(1)' },
          },
        }
      : {};

  // if session ended (mock), show results immediately
  useEffect(() => {
    if (session.status === 'end' && session.results) {
      setPhase('finished');
      setRevealed([session.results.result_1, session.results.result_2, session.results.result_3]);
      setWinners([session.results.result_1, session.results.result_2, session.results.result_3]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [session.id]);

  useEffect(() => {
    if (soldOut && phase === 'selling' && session.status !== 'end') {
      setPhase('waiting');
      setCountdown(delayTotal);
    }
  }, [soldOut, phase, delayTotal, session.status]);

  // WAITING countdown
  useEffect(() => {
    if (phase !== 'waiting') return;
    if (countdown <= 0) {
      setPhase('drawing');
      setDrawingProgress(0);
      draw();
      return;
    }
    const t = setTimeout(() => setCountdown((s) => s - 1), 1000);
    return () => clearTimeout(t);
  }, [phase, countdown]);

  // DRAWING progress animation
  useEffect(() => {
    if (phase !== 'drawing') {
      if (drawProgressRef.current) clearInterval(drawProgressRef.current as any);
      return;
    }
    let p = 0;
    drawProgressRef.current && clearInterval(drawProgressRef.current as any);
    drawProgressRef.current = setInterval(() => {
      p = Math.min(100, p + 4);
      setDrawingProgress(p);
      if (p >= 100 && drawProgressRef.current) clearInterval(drawProgressRef.current as any);
    }, 100);
    return () => {
      drawProgressRef.current && clearInterval(drawProgressRef.current as any);
    };
  }, [phase]);

  // AUTO-VENTE
  useEffect(() => {
    if (autoSell && phase === 'selling') {
      autoSellRef.current && clearInterval(autoSellRef.current as any);
      autoSellRef.current = setInterval(
        () => sellByBots(Math.random() < 0.6 ? 4 : 2),
        isXs ? 350 : 250
      );
    } else {
      autoSellRef.current && clearInterval(autoSellRef.current as any);
    }
    return () => {
      autoSellRef.current && clearInterval(autoSellRef.current as any);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoSell, phase, board, isXs]);

  function changeSession(id: string) {
    const s = MOCK_SESSIONS.find((x) => x.id === id);
    if (!s) return;
    setSession(s);
    setBoard(buildBoardFromSession(s));
    setMyTickets(Array.from(new Set(s.purchased.mine)));
    setSelected(null);
    setWinners(
      s.status === 'end' && s.results
        ? [s.results.result_1, s.results.result_2, s.results.result_3]
        : []
    );
    setRevealed(
      s.status === 'end' && s.results
        ? [s.results.result_1, s.results.result_2, s.results.result_3]
        : []
    );
    setPhase(s.status === 'end' ? 'finished' : 'selling');
    setCountdown(0);
    setDrawingProgress(0);
    revealTimerRef.current && clearTimeout(revealTimerRef.current);
  }

  function resetAll() {
    changeSession(session.id);
  }

  function sellByBots(take: number) {
    setBoard((prev) => {
      if (phase !== 'selling') return prev;
      const remaining = prev.filter((c) => c.owner === null);
      if (!remaining.length) return prev;
      const indices = new Set<number>();
      while (indices.size < Math.min(take, remaining.length)) {
        indices.add(Math.floor(Math.random() * remaining.length));
      }
      const chosen = new Set<Ball>(Array.from(indices).map((i) => remaining[i].n));
      return prev.map((c) => (chosen.has(c.n) && c.owner === null ? { ...c, owner: 'other' } : c));
    });
  }

  function randomWinners(): Ball[] {
    const soldBalls = board.filter((c) => c.owner !== null).map((c) => c.n);
    const shuffled = [...soldBalls].sort(() => Math.random() - 0.5);
    return [shuffled[0], shuffled[1], shuffled[2]];
  }

  function draw() {
    if (session.status === 'end' && session.results) {
      const win = [
        session.results.result_1,
        session.results.result_2,
        session.results.result_3,
      ] as Ball[];
      setWinners(win);
      setRevealed([]);
      const step = (i: number) => {
        setRevealed((r) => [...r, win[i]]);
        if (i < 2) revealTimerRef.current = setTimeout(() => step(i + 1), 1100);
        else revealTimerRef.current = setTimeout(() => setPhase('finished'), 700);
      };
      revealTimerRef.current = setTimeout(() => step(0), 500);
      return;
    }
    const win = randomWinners();
    setWinners(win);
    setRevealed([]);
    const step = (i: number) => {
      setRevealed((r) => [...r, win[i]]);
      if (i < 2) revealTimerRef.current = setTimeout(() => step(i + 1), 1100);
      else revealTimerRef.current = setTimeout(() => setPhase('finished'), 700);
    };
    revealTimerRef.current = setTimeout(() => step(0), 500);
  }

  function buy() {
    if (selected == null) return;
    const cell = board.find((c) => c.n === selected);
    if (!cell || cell.owner !== null) return;

    const limit = session.limitPerUser; // null => illimité
    if (session.type === 'free' && typeof limit === 'number' && myTickets.length >= limit) return;

    setBoard((prev) => prev.map((c) => (c.n === selected ? { ...c, owner: 'me' as Owner } : c)));
    setMyTickets((t) => [...t, selected]);
    setSelected(null);

    if (!autoSell) sellByBots(5);
  }

  const winsState = useMemo(() => {
    const [w0, w1, w2] = winners;
    return {
      main: !!w0 && myTickets.includes(w0),
      second: !!w1 && myTickets.includes(w1),
      third: !!w2 && myTickets.includes(w2),
    };
  }, [winners, myTickets]);

  // winners UI data (with masked names + payout)
  const rankMap = useMemo(() => {
    const m = new Map<Ball, number>();
    winners.forEach((b, i) => {
      if (b) m.set(b, i);
    });
    return m;
  }, [winners]);

  const winnersUi = useMemo(() => {
    const list = (session.results?.wins || [])
      .map((w) => {
        const rank = rankMap.has(w.ball) ? (rankMap.get(w.ball) as number) : -1;
        const mult = rank >= 0 ? session.payoutsMultipliers[rank] : 0;
        const payout = session.stake * mult;
        return { ...w, userMasked: maskName(w.user), rank, mult, payout };
      })
      .filter((x) => x.rank >= 0)
      .sort((a, b) => a.rank - b.rank);
    return list;
  }, [session.results?.wins, rankMap, session.payoutsMultipliers, session.stake]);

  const rankBadge = (r: number) => (r === 0 ? '🏆 1er' : r === 1 ? '🥈 2e' : '🥉 3e');

  const hudColor =
    phase === 'selling'
      ? '#6cf'
      : phase === 'waiting'
        ? '#ffd45e'
        : phase === 'drawing'
          ? '#9cf'
          : '#7ee287';

  // Responsive sizes
  const cellH = isXs ? 44 : isMd ? 54 : 58;
  const fontSz = isXs ? 12 : 14;
  const [m1, m2, m3] = session.payoutsMultipliers;

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: '#0c1420', color: 'white', p: { xs: 1.5, sm: 2 } }}>
      {/* HUD */}
      <Stack
        direction={{ xs: 'column', md: 'row' }}
        alignItems={{ xs: 'stretch', md: 'center' }}
        spacing={1.2}
        sx={{ mb: 2 }}
      >
        <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
          <Button
            onClick={onBack}
            startIcon={<Icon icon="solar:alt-arrow-left-bold" />}
            sx={{ bgcolor: '#10223a', color: '#9ec8ff' }}
          >
            Sessions
          </Button>
          <Chip
            icon={<Icon icon="solar:gamepad-bold" />}
            label={session.name}
            sx={{ bgcolor: '#152238', color: 'white', fontWeight: 700 }}
          />
          <Chip
            icon={<Icon icon="solar:wallet-bold" />}
            label={session.type === 'paid' ? `Stake: $${session.stake}` : 'Free session'}
            sx={{ bgcolor: '#152238', color: 'white' }}
          />
          <Chip
            icon={<Icon icon="solar:clock-circle-bold" />}
            label={
              phase === 'waiting'
                ? `Tirage dans ${Math.floor(countdown / 60)}:${String(countdown % 60).padStart(
                    2,
                    '0'
                  )}`
                : phase === 'selling'
                  ? 'En vente'
                  : phase === 'drawing'
                    ? 'Tirage en cours'
                    : 'Terminé'
            }
            sx={{ bgcolor: hudColor, color: '#061018', fontWeight: 700 }}
          />
          <Stack
            direction="row"
            spacing={0.5}
            alignItems="center"
            sx={{
              bgcolor: '#0f1e32',
              px: 1,
              py: 0.5,
              borderRadius: 2,
              border: '1px solid #21324c',
            }}
          >
            <Icon icon="solar:robot-bold" fontSize={18} />
            <Typography variant="body2" sx={{ mr: 0.5 }}>
              Auto-vente
            </Typography>
            <Switch checked={autoSell} onChange={(e) => setAutoSell(e.target.checked)} />
          </Stack>
        </Stack>

        <Box flexGrow={1} />

        <Stack
          direction="row"
          spacing={1}
          alignItems="center"
          justifyContent={{ xs: 'space-between', md: 'flex-end' }}
        >
          <Select
            size="small"
            value={session.id}
            onChange={(e) => changeSession(String(e.target.value))}
            sx={{
              bgcolor: '#0f1e32',
              color: 'white',
              '.MuiOutlinedInput-notchedOutline': { borderColor: '#21324c' },
              maxWidth: 200,
            }}
          >
            {MOCK_SESSIONS.map((s) => (
              <MenuItem key={s.id} value={s.id}>
                {s.name} {s.type === 'free' ? '• Free' : ''} {s.status === 'end' ? '• Terminé' : ''}
              </MenuItem>
            ))}
          </Select>
          <Chip
            icon={<Icon icon="solar:percent-bold" />}
            label={`Payouts ${session.payoutsMultipliers.join(' / ')}`}
            sx={{ bgcolor: '#152238', color: 'white' }}
          />
          <Chip
            icon={<Icon icon="solar:settings-bold" />}
            label={session.limitPerUser ? `Limite: ${session.limitPerUser}` : 'Illimité'}
            sx={{ bgcolor: '#152238', color: 'white' }}
          />
        </Stack>
      </Stack>

      {/* Progress */}
      <LinearProgress
        variant="determinate"
        value={Math.max(0, Math.min(100, progressValue))}
        sx={{
          height: 8,
          borderRadius: 999,
          bgcolor: '#0f1e32',
          '& .MuiLinearProgress-bar': { bgcolor: 'primary.main' },
          mb: 2,
          ...progressAnimation,
        }}
      />

      {/* DRAW OR GRID */}
      {phase !== 'selling' ? (
        <Card
          sx={{
            bgcolor: '#0f1e32',
            border: '1px solid #1e2f4a',
            boxShadow: '0 0 30px rgba(0,0,0,.5) inset',
          }}
        >
          <CardContent>
            <Stack alignItems="center" spacing={3} sx={{ py: { xs: 2, md: 3 } }}>
              <Typography variant={isXs ? 'h6' : 'h5'} fontWeight={800} sx={{ color: 'white' }}>
                Tirage
              </Typography>
              <Stack
                direction="row"
                spacing={isXs ? 1 : 2}
                alignItems="center"
                flexWrap="wrap"
                justifyContent="center"
              >
                {[0, 1, 2].map((i) => {
                  const shown = revealed[i] ?? null;
                  const mult = session.payoutsMultipliers[i];
                  return (
                    <Box
                      key={i}
                      sx={{
                        width: isXs ? 92 : 120,
                        height: isXs ? 92 : 120,
                        borderRadius: '20px',
                        bgcolor: '#0b1a2b',
                        border: '2px solid #28476e',
                        boxShadow:
                          '0 0 20px rgba(120,180,255,.25), inset 0 0 30px rgba(20,40,80,.6)',
                        display: 'grid',
                        placeItems: 'center',
                        position: 'relative',
                        transform: shown ? 'scale(1)' : 'scale(.9)',
                        transition: 'transform .3s ease',
                      }}
                    >
                      <Typography
                        variant={isXs ? 'h4' : 'h3'}
                        fontWeight={900}
                        sx={{
                          letterSpacing: 2,
                          textShadow: '0 0 10px rgba(255,255,255,.15)',
                          opacity: shown ? 1 : 0.3,
                          color: i === 0 ? '#73ffa4' : i === 1 ? '#84b6ff' : '#ffd66b',
                        }}
                      >
                        {shown ?? '• •'}
                      </Typography>
                      <Chip
                        size="small"
                        label={`x${mult}`}
                        sx={{
                          position: 'absolute',
                          bottom: 8,
                          bgcolor: i === 0 ? '#73ffa4' : i === 1 ? '#84b6ff' : '#ffd66b',
                          color: '#03121f',
                          fontWeight: 800,
                        }}
                      />
                    </Box>
                  );
                })}
              </Stack>

              {/* winners & wins */}
              <Stack spacing={1} alignItems="center" sx={{ width: '100%' }}>
                {(phase === 'finished' || session.status === 'end') && (
                  <>
                    {/* winners cards (styled) */}
                    {Boolean(winnersUi.length) && (
                      <Grid
                        container
                        spacing={1.2}
                        justifyContent="center"
                        sx={{ width: '100%', maxWidth: 900, px: 1 }}
                      >
                        {winnersUi.map((w) => {
                          const isMain = w.rank === 0;
                          const isSecond = w.rank === 1;
                          const grad = isMain
                            ? 'linear-gradient(135deg, #0e2b1f 0%, #1d3f33 60%, #0e2b1f 100%)'
                            : isSecond
                              ? 'linear-gradient(135deg, #0e1d2b 0%, #1a3250 60%, #0e1d2b 100%)'
                              : 'linear-gradient(135deg, #2b240e 0%, #534218 60%, #2b240e 100%)';
                          const ring = isMain ? '#2bd67b' : isSecond ? '#84b6ff' : '#ffd66b';

                          return (
                            <Grid key={`${w.ball}-${w.user}`} item xs={12} sm={10} md={8}>
                              <Box
                                sx={{
                                  p: 1.2,
                                  borderRadius: 2.5,
                                  bgcolor: '#0b1624',
                                  border: `1px solid ${ring}55`,
                                  boxShadow: `0 0 0 1px ${ring}22, 0 10px 30px ${ring}22, inset 0 0 40px ${ring}11`,
                                }}
                              >
                                <Box
                                  sx={{
                                    p: { xs: 1.2, sm: 1.6 },
                                    borderRadius: 2,
                                    background: grad,
                                    position: 'relative',
                                    overflow: 'hidden',
                                    '&::after': {
                                      content: '""',
                                      position: 'absolute',
                                      inset: 0,
                                      background:
                                        'radial-gradient(1000px 200px at -20% -40%, rgba(255,255,255,0.08), transparent), radial-gradient(700px 160px at 120% 140%, rgba(255,255,255,0.06), transparent)',
                                      pointerEvents: 'none',
                                    },
                                  }}
                                >
                                  <Stack
                                    direction={{ xs: 'column', sm: 'row' }}
                                    spacing={1.2}
                                    alignItems={{ xs: 'flex-start', sm: 'center' }}
                                    justifyContent="space-between"
                                  >
                                    <Stack
                                      direction="row"
                                      spacing={1.2}
                                      alignItems="center"
                                      flexWrap="wrap"
                                    >
                                      <Icon
                                        icon={
                                          isMain
                                            ? 'solar:crown-bold'
                                            : isSecond
                                              ? 'solar:medal-ribbons-star-bold'
                                              : 'solar:medal-star-bold'
                                        }
                                        fontSize={22}
                                        color={ring}
                                        style={{
                                          filter: 'drop-shadow(0 2px 8px rgba(0,0,0,.35))',
                                        }}
                                      />
                                      <Typography
                                        variant="h6"
                                        fontWeight={900}
                                        sx={{ letterSpacing: 0.4, color: 'white' }}
                                      >
                                        {w.userMasked}
                                      </Typography>
                                      <Chip
                                        size="small"
                                        label={`#${w.ball}`}
                                        sx={{
                                          bgcolor: '#0e2238',
                                          color: '#cfe4ff',
                                          border: `1px solid ${ring}55`,
                                        }}
                                      />
                                      <Chip
                                        size="small"
                                        label={`${rankBadge(w.rank)} • x${w.mult}`}
                                        sx={{
                                          bgcolor: ring,
                                          color: '#072018',
                                          fontWeight: 900,
                                        }}
                                      />
                                    </Stack>

                                    <Stack alignItems={{ xs: 'flex-start', sm: 'flex-end' }}>
                                      <Typography
                                        fontSize={12}
                                        sx={{ opacity: 0.7, mb: 0.25, color: 'white' }}
                                      >
                                        Gain
                                      </Typography>
                                      <Typography
                                        variant="h5"
                                        fontWeight={900}
                                        sx={{
                                          textShadow: '0 2px 14px rgba(0,0,0,.35)',
                                          color: 'white',
                                        }}
                                      >
                                        {session.stake > 0 ? `$${money(w.payout)}` : `x${w.mult}`}
                                      </Typography>
                                    </Stack>
                                  </Stack>
                                </Box>
                              </Box>
                            </Grid>
                          );
                        })}
                      </Grid>
                    )}
                  </>
                )}
              </Stack>
            </Stack>
          </CardContent>
        </Card>
      ) : (
        <>
          {/* GRID */}
          <Card
            sx={{
              bgcolor: '#0f1e32',
              border: '1px solid #1e2f4a',
              boxShadow: '0 0 30px rgba(0,0,0,.5) inset',
            }}
          >
            <CardContent sx={{ p: { xs: 1, sm: 2 } }}>
              <Grid
                container
                spacing={isXs ? 0.7 : 1.2}
                columns={11}
                sx={{ justifyContent: 'center' }}
              >
                {board.map((cell) => {
                  const isMine = cell.owner === 'me';
                  const isOther = cell.owner === 'other';
                  const available = cell.owner === null;
                  const selectedHere = selected === cell.n;
                  const bg = isMine ? '#2bd67b' : isOther ? '#7a8699' : '#2f8fff';
                  const dim = !available && !isMine ? 0.55 : 1;

                  return (
                    <Grid key={cell.n} item xs={1}>
                      <Box
                        onClick={() => {
                          if (!available) return;
                          setSelected((prev) => (prev === cell.n ? null : cell.n));
                        }}
                        sx={{
                          height: cellH,
                          borderRadius: isXs ? '14px' : '18px',
                          display: 'grid',
                          placeItems: 'center',
                          cursor: available ? 'pointer' : 'not-allowed',
                          background:
                            selectedHere && available
                              ? `linear-gradient(180deg, ${bg}, #123a66)`
                              : `linear-gradient(180deg, #0b1a2b, #0a1522)`,
                          border: selectedHere ? `2px solid ${bg}` : '2px solid #254566',
                          boxShadow: selectedHere
                            ? `0 0 18px ${bg}88, inset 0 0 26px rgba(20,40,80,.8)`
                            : 'inset 0 0 24px rgba(20,40,80,.8)',
                          position: 'relative',
                          transition: 'all .15s ease',
                          opacity: dim,
                          '&:hover': { transform: available ? 'translateY(-2px)' : 'none' },
                          color: isMine ? 'primary.dark' : isOther ? '#ffffff' : '#cfe4ff',
                        }}
                      >
                        <Typography fontWeight={800} fontSize={fontSz}>
                          {cell.n}
                        </Typography>
                        <Box
                          sx={{
                            position: 'absolute',
                            inset: 3,
                            borderRadius: isXs ? '10px' : '14px',
                            boxShadow: `0 0 18px ${
                              isMine ? '#2bd67b55' : isOther ? '#ffffff18' : '#2f8fff33'
                            }`,
                            pointerEvents: 'none',
                          }}
                        />
                        {isMine && (
                          <Icon
                            icon="solar:check-circle-bold"
                            style={{
                              position: 'absolute',
                              right: 6,
                              bottom: 6,
                              fontSize: 16,
                              color: '#0b1a2b',
                              filter: 'drop-shadow(0 0 6px rgba(255,255,255,.6))',
                            }}
                          />
                        )}
                      </Box>
                    </Grid>
                  );
                })}
              </Grid>
            </CardContent>
          </Card>

          {/* ACTIONS */}
          <Stack
            direction={{ xs: 'column', md: 'row' }}
            spacing={1.2}
            sx={{ mt: 2 }}
            alignItems="stretch"
          >
            <Card sx={{ flex: 1, bgcolor: '#0f1e32', border: '1px solid #1e2f4a' }}>
              <CardContent sx={{ p: { xs: 1.2, sm: 2 } }}>
                <Stack
                  direction={{ xs: 'column', sm: 'row' }}
                  alignItems={{ xs: 'stretch', sm: 'center' }}
                  justifyContent="space-between"
                  spacing={1.2}
                >
                  <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap">
                    <Chip
                      icon={<Icon icon="solar:bag-4-bold" />}
                      label={`À payer: $${selected != null ? session.stake : 0}`}
                      sx={{ bgcolor: '#1b2c46', color: 'white', fontWeight: 700 }}
                    />
                    <Divider
                      flexItem
                      orientation="vertical"
                      sx={{ display: { xs: 'none', sm: 'block' }, borderColor: '#28476e' }}
                    />
                    <Chip
                      icon={<Icon icon="solar:ticket-bold" />}
                      label={`Mes numéros: ${myTickets.length ? myTickets.join(' • ') : '—'}`}
                      sx={{ bgcolor: '#1b2c46', color: 'white' }}
                    />
                  </Stack>
                  <Stack direction="row" spacing={1}>
                    <Button
                      variant="outlined"
                      startIcon={<Icon icon="solar:refresh-bold" />}
                      onClick={resetAll}
                      sx={{
                        borderColor: '#355781',
                        color: 'white',
                        ':hover': { borderColor: '#5a8ad1' },
                      }}
                    >
                      Reset
                    </Button>
                    <Button
                      variant="contained"
                      startIcon={<Icon icon="solar:cart-5-bold" />}
                      disabled={
                        selected == null ||
                        (session.type === 'free' &&
                          typeof session.limitPerUser === 'number' &&
                          myTickets.length >= session.limitPerUser)
                      }
                      onClick={buy}
                      sx={{
                        bgcolor: selected != null ? '#2bd67b' : '#3a5a80',
                        color: '#06202a',
                        fontWeight: 900,
                        minWidth: 140,
                        ':disabled': { bgcolor: '#314966', color: '#96a5b6' },
                        ':hover': {
                          bgcolor: selected != null ? 'primary.main' : '#3a5a80',
                        },
                      }}
                    >
                      Acheter
                    </Button>
                  </Stack>
                </Stack>
              </CardContent>
            </Card>
          </Stack>
        </>
      )}
    </Box>
  );
}
